package com.digitalhealth.service;
import com.digitalhealth.dto.MedicalReportDTO; import com.digitalhealth.model.*; import com.digitalhealth.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException; import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*;
@Service public class MedicalReportService {private final MedicalReportRepository reports;private final WorkerRepository workers;private final Path storage;private static final Set<String> TYPES=Set.of("application/pdf","image/jpeg","image/png");public MedicalReportService(MedicalReportRepository r,WorkerRepository w,@Value("${app.storage.directory}") String dir){reports=r;workers=w;storage=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(storage);}catch(IOException e){throw new IllegalStateException("Unable to create private report storage",e);}} public MedicalReportDTO upload(Long workerId,String title,String type,LocalDate date,String center,String description,MultipartFile file){if(file==null||file.isEmpty()||file.getSize()>10*1024*1024||!TYPES.contains(file.getContentType()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only PDF, PNG, and JPEG files up to 10 MB are accepted");String original=Paths.get(Objects.requireNonNullElse(file.getOriginalFilename(),"report")).getFileName().toString();if(!original.matches("[A-Za-z0-9._ -]{1,160}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid file name");Worker w=workers.findById(workerId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Worker not found"));String stored=UUID.randomUUID()+original.substring(original.lastIndexOf('.'));try(InputStream in=file.getInputStream()){Files.copy(in,storage.resolve(stored),StandardCopyOption.REPLACE_EXISTING);}catch(IOException e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Report upload failed");}MedicalReport r=new MedicalReport();r.setWorker(w);r.setTitle(title);r.setReportType(type);r.setReportDate(date);r.setHealthcareCenter(center);r.setDescription(description);r.setStoredName(stored);r.setOriginalName(original);r.setContentType(file.getContentType());r.setFileSize(file.getSize());return dto(reports.save(r));} public List<MedicalReportDTO> list(Long id){return reports.findByWorkerIdOrderByReportDateDesc(id).stream().map(this::dto).toList();} public MedicalReport get(Long workerId,Long id){return reports.findById(id).filter(r->r.getWorker().getId().equals(workerId)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Medical report not found"));} public ResourceFile file(Long w,Long id){MedicalReport r=get(w,id);try{return new ResourceFile(r,Files.readAllBytes(storage.resolve(r.getStoredName())));}catch(IOException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Report file is unavailable");}} public void delete(Long w,Long id){MedicalReport r=get(w,id);try{Files.deleteIfExists(storage.resolve(r.getStoredName()));}catch(IOException ignored){}reports.delete(r);} private MedicalReportDTO dto(MedicalReport r){var d=new MedicalReportDTO();d.id=r.getId();d.title=r.getTitle();d.reportType=r.getReportType();d.reportDate=r.getReportDate();d.healthcareCenter=r.getHealthcareCenter();d.description=r.getDescription();d.originalName=r.getOriginalName();d.contentType=r.getContentType();d.fileSize=r.getFileSize();d.createdAt=r.getCreatedAt();return d;} public record ResourceFile(MedicalReport report,byte[] bytes){} }
